import type {HandoffScope} from './cashier-handoff';
export type CashierVariancePostingSelection={scope:HandoffScope;session:string;mapping:string;expense:string;cash:string;amount:string;period:string;date:string};
const uuid=(v:unknown):v is string=>typeof v==='string'&&/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/.test(v);
function obj(v:unknown):Record<string,unknown>{if(!v||typeof v!=='object'||Array.isArray(v))throw Error('Invalid cash variance preview.');return v as Record<string,unknown>}
function date(v:unknown):v is string{return typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!Number.isNaN(Date.parse(v))&&new Date(v).toISOString().slice(0,10)===v}
export function readCashierVariancePostingPreview(value:unknown,s:CashierVariancePostingSelection){const v=obj(value),c=obj(v.command);
 if(![...Object.values(s.scope),s.session,s.mapping,s.expense,s.cash,s.period].every(uuid)||s.expense===s.cash||!date(s.date)||! /^-?[1-9][0-9]{0,11}$/.test(s.amount))throw Error('Invalid cash variance selection.');
 if(v.schema_version!==1||v.tenant_id!==s.scope.tenant||v.property_id!==s.scope.property||v.actor_id!==s.scope.actor||v.session_id!==s.session||v.mapping_id!==s.mapping||v.expense_account_id!==s.expense||v.variance_minor!==s.amount||v.period_id!==s.period||v.posting_date!==s.date||typeof v.review_revision!=='string'||! /^[1-9][0-9]*$/.test(v.review_revision)||!uuid(v.review_request_id)||v.journal_posted!==false)throw Error('Bank debit preview changed.');
 if(c.currency!=='USD'||c.description!=='Cash drawer shortage or overage'||c.source_kind!=='cashier_variance'||c.source_id!==s.session||String(c.source_version)!==v.review_revision||c.period_id!==s.period||c.posting_date!==s.date||!Array.isArray(c.lines)||c.lines.length!==2)throw Error('Invalid cash variance command.');
 const cash=obj(c.lines[0]),expense=obj(c.lines[1]),positive=BigInt(s.amount)>BigInt(0),amount=(positive?BigInt(s.amount):-BigInt(s.amount)).toString();if(cash.account_id!==s.cash||expense.account_id!==s.expense||cash.side!==(positive?'debit':'credit')||expense.side!==(positive?'credit':'debit')||cash.amount_minor!==amount||expense.amount_minor!==amount)throw Error('Variance accounts or amounts changed.');return v;
}
export type CashierVariancePostingRequest={id:string;selection:CashierVariancePostingSelection;review:Record<string,unknown>};
function checked(r:CashierVariancePostingRequest){if(!uuid(r.id))throw Error('Invalid cash variance request.');readCashierVariancePostingPreview(r.review,r.selection);return r}
export function readCashierVariancePostingReceipt(value:unknown,r:CashierVariancePostingRequest){checked(r);const v=obj(value),s=r.selection;if(v.schema_version!==1||v.tenant_id!==s.scope.tenant||v.property_id!==s.scope.property||v.actor_id!==s.scope.actor||v.request_id!==r.id||v.session_id!==s.session||v.variance_minor!==s.amount||!uuid(v.journal_id)||typeof v.replayed!=='boolean'||v.journal_posted!==true||v.cash_recovered!==false)throw Error('Variance receipt does not match the saved request.');return v}
function canonical(value:unknown):string{if(Array.isArray(value))return '['+value.map(canonical).join(',')+']';if(value&&typeof value==='object')return '{'+Object.entries(value).sort(([a],[b])=>a.localeCompare(b)).map(([k,v])=>JSON.stringify(k)+':'+canonical(v)).join(',')+'}';return JSON.stringify(value)}
export function readCashierVariancePostingStatus(value:unknown,r:CashierVariancePostingRequest){checked(r);const v=obj(value),s=r.selection.scope;if(v.schema_version!==1||v.tenant_id!==s.tenant||v.property_id!==s.property||v.actor_id!==s.actor||v.request_id!==r.id||typeof v.found!=='boolean'||typeof v.cancelled!=='boolean'||typeof v.journal_reversed!=='boolean'||(v.found&&v.cancelled))throw Error('Variance recovery scope changed.');if(!v.found){if(v.result!==null||v.review!==null||v.journal_reversed)throw Error('Invalid cash variance recovery.');return {state:v.cancelled?'cancelled' as const:'missing' as const,result:null,reversed:false}}if(canonical(v.review)!==canonical(r.review))throw Error('Recovered cash variance has a different review.');return {state:'posted' as const,result:readCashierVariancePostingReceipt(v.result,r),reversed:v.journal_reversed}}
type Store=Pick<Storage,'getItem'|'setItem'|'removeItem'>;
function storageKey(scope:HandoffScope,session:string){if(![...Object.values(scope),session].every(uuid))throw Error('Invalid cash variance storage scope.');return 'irp.cash.variance.posting.v1:'+[scope.tenant,scope.property,scope.actor].join(':')+':'+session}
export function retainCashierVariancePosting(store:Store,r:CashierVariancePostingRequest){checked(r);const key=storageKey(r.selection.scope,r.selection.session),prior=store.getItem(key);if(prior!==null&&canonical(JSON.parse(prior))!==canonical(r))throw Error('Recover or cancel the previous cash variance first.');store.setItem(key,JSON.stringify(r));if(store.getItem(key)!==JSON.stringify(r))throw Error('Unable to retain cash variance request.');}
export function restoreCashierVariancePosting(store:Store,scope:HandoffScope,session:string){const raw=store.getItem(storageKey(scope,session));if(raw===null)return null;const r=JSON.parse(raw) as CashierVariancePostingRequest;checked(r);if(canonical(r.selection.scope)!==canonical(scope)||r.selection.session!==session)throw Error('Saved cash variance belongs to another workspace.');return r}
export function clearCashierVariancePosting(store:Store,r:CashierVariancePostingRequest,status:unknown){const parsed=readCashierVariancePostingStatus(status,r);if(parsed.state==='missing')throw Error('Check or cancel the cash variance before clearing it.');const key=storageKey(r.selection.scope,r.selection.session),prior=restoreCashierVariancePosting(store,r.selection.scope,r.selection.session);if(prior&&canonical(prior)!==canonical(r))throw Error('Saved cash variance changed.');store.removeItem(key);return parsed}
